/**
 * #2 / S4 — cross-program declare_program! CPI, BYTE-EQUAL gated.
 *
 * The `hand` program (solana-developers/program-examples cross-program-
 * invocation/anchor) CPIs into `lever::switch_power` via the Anchor CPI-helper
 * form generated by `declare_program!(lever)`:
 *   let cpi_ctx = CpiContext::new(ctx.accounts.lever_program.key(), SwitchPower { power: ... });
 *   switch_power(cpi_ctx, name)?;
 *
 * Anvil's pre-parse rewrite (externalIdls) turns this into the hand-built
 * Instruction + invoke shape its generic-CPI path emits. This differential
 * proves the emitted Anvil `hand` and the real Anchor `hand` produce
 * BYTE-IDENTICAL PowerStatus after pull_lever — i.e. the synthesized
 * discriminator + account metas + Borsh arg encoding all match. lever.so is
 * loaded as the committed callee (auxiliaryPrograms); the CPI flows through it
 * identically on both sides, so any wrong meta/data on the Anvil side would
 * make the CPI revert/misbehave and the compare would DIVERGE.
 *
 * Gates the whole declare_program! arc. Skips (loud) if the upstream repo isn't
 * cloned or the SBF/anchor toolchain is unavailable.
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { TEST_SCRATCH } from "./scratch-root.ts";
import { Transaction, TransactionInstruction, SystemProgram } from "@solana/web3.js";
import {
  defineDifferential,
  anchorIxDiscriminator,
  concatBytes,
  Keypair,
  PublicKey,
  LiteSVM,
} from "./differential-harness.ts";
import { REPO_PATH, ensureRepoCloned } from "./fixtures/program-examples-cpi-lever-fixture.ts";

const LEVER_ID = "E64FVeubGC4NPNF2UBJYX4AkrVowf74fRJD9q6YhwstN";
const HAND_ID = "Bi5N7SUQhpGknVcqPTzdFFVueQoxoUu8YTLz75J6fT8A";
const BASE = `${REPO_PATH}/basics/cross-program-invocation/anchor`;
const HAND_LIB_RS = `${BASE}/programs/hand/src/lib.rs`;
const LEVER_IDL = `${BASE}/idls/lever.json`;

// Standalone single-crate build dir for the Anchor `hand` reference (avoids the
// workspace's shared target/deploy that holds both hand.so + lever.so). Mirrors
// the layout verified to resolve declare_program!(lever) from idls/lever.json.
const HAND_CARGO = `[package]
name = "hand"
version = "0.1.0"
edition = "2021"
[lib]
crate-type = ["cdylib", "lib"]
name = "hand"
[features]
no-entrypoint = []
default = []
[dependencies]
anchor-lang = "1.0.0"
[profile.release]
overflow-checks = true
`;

// The harness deploys the reference at HAND_ID, but the standalone-crate
// build path compiles the crate dir AS-IS (no rewriteDeclareId like the
// normal anchor-build path) — with the upstream declare_id! left in place,
// every hand instruction reverts with AnchorError 4100
// DeclaredProgramIdMismatch, which surfaced as a bogus data mismatch
// (corpus take-3, #34). Rewrite the id ONCE here and use it for BOTH the
// crate write and the anchorSource the harness hashes, so the source-hash
// cache can't resurrect a pre-rewrite .so.
function handSourceAtDeployId(): string {
  return readFileSync(HAND_LIB_RS, "utf-8").replace(/declare_id!\("[^"]+"\)/, `declare_id!("${HAND_ID}")`);
}

// Same class of drift for the CALLEE: the upstream lever.json IDL says
// `address: A6GUsa…` but the committed lever.so declares (and the test
// deploys at) E64FVe…. Anchor's declare_program!-typed `power` account
// owner-checks against the IDL address, so the reference reverted with
// 3007 AccountOwnedByWrongProgram. Pin the IDL to the deploy id for both
// the reference crate and the Anvil parse side.
function leverIdlAtDeployId(): Record<string, unknown> {
  const idl = JSON.parse(readFileSync(LEVER_IDL, "utf-8"));
  idl.address = LEVER_ID;
  return idl;
}

function prepareHandCrate(): string | null {
  if (!existsSync(HAND_LIB_RS) || !existsSync(LEVER_IDL)) return null;
  const dir = join(TEST_SCRATCH, "anvil-cpi-lever-hand");
  mkdirSync(join(dir, "src"), { recursive: true });
  mkdirSync(join(dir, "idls"), { recursive: true });
  writeFileSync(join(dir, "src/lib.rs"), handSourceAtDeployId());
  writeFileSync(join(dir, "idls/lever.json"), JSON.stringify(leverIdlAtDeployId()));
  writeFileSync(join(dir, "Cargo.toml"), HAND_CARGO);
  return dir;
}

ensureRepoCloned();

if (!existsSync(HAND_LIB_RS) || !existsSync(LEVER_IDL)) {
  console.warn(
    `[differential-cpi-lever-hand] SKIPPED — ${HAND_LIB_RS} or ${LEVER_IDL} missing (repo not cloned).`,
  );
} else {
  const crateDir = prepareHandCrate()!;
  const handSource = handSourceAtDeployId();
  const leverIdl = leverIdlAtDeployId();

  function borshString(s: string): Uint8Array {
    const bytes = new TextEncoder().encode(s);
    const out = new Uint8Array(4 + bytes.length);
    new DataView(out.buffer).setUint32(0, bytes.length, true);
    out.set(bytes, 4);
    return out;
  }

  defineDifferential({
    fixtureName: "program-examples-cpi-lever-hand",
    programIdBase58: HAND_ID,
    anchorSource: handSource,
    anchorPackageName: "hand",
    anchorReferenceCrateDir: crateDir,
    externalIdls: { lever: leverIdl },
    auxiliaryPrograms: [{ programId: LEVER_ID, soFilename: "lever.so" }],
    compareTxOutcomes: true,

    setup: async () => ({ payer: Keypair.generate(), power: Keypair.generate(), name: "Chekov" }),

    callScript: async (svm: LiteSVM, ctx, programId: PublicKey) => {
      const leverId = new PublicKey(LEVER_ID);
      svm.airdrop(ctx.payer.publicKey, BigInt(2_000_000_000));

      // initialize PowerStatus directly via lever (power + payer sign).
      const initIx = new TransactionInstruction({
        programId: leverId,
        keys: [
          { pubkey: ctx.power.publicKey, isSigner: true, isWritable: true },
          { pubkey: ctx.payer.publicKey, isSigner: true, isWritable: true },
          { pubkey: SystemProgram.programId, isSigner: false, isWritable: false },
        ],
        data: Buffer.from(anchorIxDiscriminator("initialize")),
      });
      {
        const tx = new Transaction().add(initIx);
        tx.recentBlockhash = svm.latestBlockhash();
        tx.feePayer = ctx.payer.publicKey;
        tx.sign(ctx.payer, ctx.power);
        svm.sendTransaction(tx);
      }

      // pull_lever via hand → CPIs lever::switch_power(name). Accounts:
      // power (mut), lever_program. payer signs (power no longer a signer).
      const pullIx = new TransactionInstruction({
        programId,
        keys: [
          { pubkey: ctx.power.publicKey, isSigner: false, isWritable: true },
          { pubkey: leverId, isSigner: false, isWritable: false },
        ],
        data: Buffer.from(concatBytes(anchorIxDiscriminator("pull_lever"), borshString(ctx.name))),
      });
      {
        const tx = new Transaction().add(pullIx);
        tx.recentBlockhash = svm.latestBlockhash();
        tx.feePayer = ctx.payer.publicKey;
        tx.sign(ctx.payer);
        svm.sendTransaction(tx);
      }
    },

    accountsToCompare: (ctx) => [{ pubkey: ctx.power.publicKey, label: "power_status" }],
  });
}
